<script setup lang="ts">
import {computed,defineAsyncComponent,nextTick,onMounted,ref,shallowRef} from 'vue';
import {unifiedWorkspace,unifiedCards,unifiedDrafts,unifiedLearning} from '../services';
import {reviewSettingsGuards} from '../composables/reviewSettingsGuard';
import {initializeTheme} from '../composables/preferences';
import type {Input,Output} from '../../shared/protocol/registry';
import UiIcon from '../components/UiIcon.vue';
function reloadAfterRestore(){window.location.reload();}
const SystemSettings=defineAsyncComponent(()=>import('./UnifiedSystemSettings.vue'));
const system=shallowRef<InstanceType<typeof SystemSettings>>();
const Exchange=defineAsyncComponent(()=>import('./UnifiedCardExchange.vue'));
const importing=ref(false),exchange=shallowRef<InstanceType<typeof Exchange>>();
const Analytics=defineAsyncComponent(()=>import('./UnifiedAnalytics.vue'));
const CatalogEditor=defineAsyncComponent(()=>import('./UnifiedCatalogEditor.vue'));
const catalogEditor=shallowRef<InstanceType<typeof CatalogEditor>>(),catalogEdit=shallowRef<{kind:'folder'|'deck';item?:Output<'workspace.catalog'>['items'][number]}|null>(null);
const CardBatch=defineAsyncComponent(()=>import('./UnifiedCardBatch.vue'));
const CardRecycle=defineAsyncComponent(()=>import('./UnifiedRecycle.vue'));
const batch=shallowRef<InstanceType<typeof CardBatch>>(),recycle=shallowRef<InstanceType<typeof CardRecycle>>();
const StudyPlanner=defineAsyncComponent(()=>import('./UnifiedStudyPlanner.vue'));
const ScheduleSettings=defineAsyncComponent(()=>import('./UnifiedScheduleSettings.vue'));
const settings=shallowRef<InstanceType<typeof ScheduleSettings>>();
const CardEditor=defineAsyncComponent(()=>import('./UnifiedCardEditor.vue'));
const CardDetail=defineAsyncComponent(()=>import('./UnifiedCardDetail.vue'));
const detail=shallowRef<InstanceType<typeof CardDetail>>();
const ReviewForm=defineAsyncComponent(()=>import('../review/UnifiedReviewForm.vue'));
const MindWorkspace=defineAsyncComponent(()=>import('../components/MindMapWorkspace.vue'));
const props=defineProps<{initialCatalog?:Output<'workspace.catalog'>}>();
const catalog=shallowRef<Output<'workspace.catalog'>>(),folder=ref<string|null>(null),catalogItems=ref<Output<'workspace.catalog'>['items']>([]),deck=shallowRef<{id:string;name:string;cardCount:number|null}>(),page=ref<'home'|'cards'|'detail'|'edit'|'review'|'knowledge'|'planner'|'settings'|'card-policy'|'recycle'|'analysis'|'overview'|'system'>('home');
const error=ref(''),notice=ref(''),busy=ref(false),query=ref(''),mode=ref<'all'|'question'|'qa'|'direct'>('all'),selection=ref<string[]>([]),cardId=ref(''),rows=ref<Output<'card.listSummary'>['items']>([]),cursor=ref<string|null>(null),drafts=ref<Output<'draft.listSummary'>['items']>([]);
const sessions=ref<Output<'workspace.sessions'>['items']>([]),activeSession=ref(''),review=shallowRef<Output<'learning.session.get'>>(),editor=shallowRef<InstanceType<typeof CardEditor>>(),reviewForm=shallowRef<InstanceType<typeof ReviewForm>>(),map=shallowRef<InstanceType<typeof MindWorkspace>>();
const selectedEvent=ref('');
const labels={question:'单选错题',qa:'问答记忆',direct:'直接记忆'};
const draftCursor=ref<string|null>(null),sessionCursor=ref<string|null>(null);
const selectedRows=computed(()=>rows.value.filter(r=>selection.value.includes(r.cardId)));
const showingMap=computed(()=>page.value==='knowledge');
const lastLists=new Map<string,{rows:Output<'card.listSummary'>['items'];cursor:string|null;query:string;mode:typeof mode.value;selection:string[];scroll:number}>();
const contentArea=ref<HTMLElement>();
let systemReturn:typeof page.value='home',systemScroll=0,listFocus='';
async function openSystem(){if(page.value==='system'||!await leave())return;systemReturn=page.value;if(page.value==='detail')selectedEvent.value=detail.value?.selectedEvent()??selectedEvent.value;systemScroll=contentArea.value?.scrollTop??0;page.value='system';await nextTick();contentArea.value?.querySelector<HTMLElement>('select,button')?.focus();}
async function returnSystem(){if(!await leave())return;if(systemReturn==='review'&&deck.value&&activeSession.value){try{review.value=await unifiedLearning.get({deckId:deck.value.id,sessionId:activeSession.value});}catch(e){error.value=String(e);return;}}page.value=systemReturn;await nextTick();if(contentArea.value)contentArea.value.scrollTop=systemScroll;document.querySelector<HTMLElement>('.unified-sidebar [aria-label=系统设置]')?.focus();}
function systemExchange(){importing.value=true;}

let navigationPending=false;
async function leave(){if(importing.value&&exchange.value?.close()===false)return false;if(navigationPending||busy.value)return false;navigationPending=true;try{importing.value=false;if(page.value==='system'&&system.value&&!await system.value.close())return false;if(catalogEdit.value){if(catalogEditor.value&&!catalogEditor.value.close())return false;catalogEdit.value=null;}if(page.value==='cards'&&batch.value&&!batch.value.close())return false;if(page.value==='recycle'&&recycle.value&&!recycle.value.close())return false;if(['settings','card-policy'].includes(page.value)){if(settings.value&&!settings.value.close())return false;for(const guard of reviewSettingsGuards)if(!guard())return false;}if(page.value==='edit'&&editor.value&&!await editor.value.close())return false;if(page.value==='review'&&reviewForm.value&&!await reviewForm.value.close())return false;if(page.value==='knowledge'&&map.value&&!await map.value.save())return false;if(page.value==='cards'&&deck.value)lastLists.set(deck.value.id,{rows:[...rows.value],cursor:cursor.value,query:query.value,mode:mode.value,selection:[...selection.value],scroll:contentArea.value?.scrollTop??0});return true;}finally{navigationPending=false;}}
async function loadCatalog(id:string|null=null,more=false){busy.value=true;error.value='';try{const result=await unifiedWorkspace.catalog({folderId:id,cursor:more?catalog.value?.nextCursor:null});catalog.value=result;catalogItems.value=more?[...catalogItems.value,...result.items]:result.items;folder.value=id;}catch(e){error.value=String(e);}finally{busy.value=false;}}
async function catalogSaved(){catalogEdit.value=null;notice.value='目录已保存';await loadCatalog(folder.value);if(error.value)error.value='目录已保存，刷新失败，请重新读取。'+error.value;}
async function home(id:string|null=null){if(!await leave())return;deck.value=undefined;page.value='home';await loadCatalog(id);}
async function openDeck(item:{id:string;name:string;cardCount:number|null}){if(!await leave())return;deck.value=item;drafts.value=[];draftCursor.value=null;sessions.value=[];sessionCursor.value=null;query.value='';mode.value='all';selection.value=[];rows.value=[];cursor.value=null;page.value='cards';await loadCards();await loadSessions();}
async function loadCards(more=false){if(!deck.value||busy.value)return;busy.value=true;error.value='';try{const result=await unifiedCards.listSummary({deckId:deck.value.id,filters:{query:query.value,...(mode.value==='all'?{}:{mode:mode.value})},cursor:more?cursor.value:null,limit:30});rows.value=more?[...rows.value,...result.items]:result.items;cursor.value=result.nextCursor;if(!more)selection.value=[];}catch(e){error.value=String(e);}finally{busy.value=false;}}
async function loadSessions(more=false){if(!deck.value)return;try{const id=deck.value.id,result=await unifiedWorkspace.sessions({deckId:id,after:more?sessionCursor.value:null});if(deck.value?.id===id){sessions.value=more?[...sessions.value,...result.items]:result.items;sessionCursor.value=result.nextCursor;}}catch(e){error.value=String(e);}}
async function cards(){if(!deck.value||!await leave())return;const remembered=lastLists.get(deck.value.id);page.value='cards';if(remembered){rows.value=remembered.rows;cursor.value=remembered.cursor;query.value=remembered.query;mode.value=remembered.mode;selection.value=remembered.selection;await nextTick();if(contentArea.value)contentArea.value.scrollTop=remembered.scroll;}else await loadCards();await loadSessions();await nextTick();if(listFocus)contentArea.value?.querySelector<HTMLElement>('[data-card-id="'+CSS.escape(listFocus)+'"] button')?.focus({preventScroll:true});}
async function viewCard(id:string,edit=false,eventId=''){if(!await leave())return;listFocus=id;cardId.value=id;selectedEvent.value=eventId;page.value=edit?'edit':'detail';}
async function create(mode:'question'|'qa'|'direct'){if(!deck.value||!await leave())return;busy.value=true;try{const d=await unifiedDrafts.create({deckId:deck.value.id,initialType:mode});cardId.value=d.cardId;page.value='edit';}catch(e){error.value=String(e);}finally{busy.value=false;}}
async function restoreDrafts(more=false){if(!deck.value||!await leave())return;busy.value=true;try{const r=await unifiedDrafts.listSummary({deckId:deck.value.id,after:more?draftCursor.value:null});drafts.value=more?[...drafts.value,...r.items]:r.items;draftCursor.value=r.nextCursor;}catch(e){error.value=String(e);}finally{busy.value=false;}}
async function switchPage(next:'knowledge'|'planner'|'settings'|'card-policy'|'recycle'|'analysis'|'overview'){if(!await leave())return;page.value=next;}
async function study(ids?:string[],practice=false){if(!deck.value||!await leave())return;busy.value=true;error.value='';try{let chosen=ids;
 if(!chosen?.length){const q=await unifiedLearning.queue({deckId:deck.value.id,filters:{query:query.value},limit:100});chosen=[...q.due,...q.relearn,...q.specialty].map(r=>r.cardId);}
 if(!chosen.length){notice.value='当前没有可复盘卡片，可在列表选择卡片开始专项复盘。';return;}
 const uniqueIds=[...new Set(chosen)],matches=await unifiedWorkspace.sessions({deckId:deck.value.id,exactCardIds:uniqueIds}),existing=matches.items.find(s=>!s.completed&&s.practiceMode===practice);
 const result=existing?await unifiedLearning.get({deckId:deck.value.id,sessionId:existing.sessionId}):await unifiedLearning.open({deckId:deck.value.id,cardIds:uniqueIds,practice});review.value=result;activeSession.value=result.sessionId;page.value='review';await loadSessions();
 }catch(e){error.value=String(e);}finally{busy.value=false;}}
async function resume(id:string){if(!deck.value||!await leave())return;busy.value=true;try{review.value=await unifiedLearning.get({deckId:deck.value.id,sessionId:id});activeSession.value=id;page.value='review';}catch(e){error.value=String(e);}finally{busy.value=false;}}
async function batchSaved(){if(!deck.value)return;lastLists.delete(deck.value.id);selection.value=[];await loadCards();if(error.value)error.value='操作已保存，列表刷新失败，请重新读取；无需重复操作。'+error.value;}
function published(){notice.value='卡片已发布';if(deck.value)lastLists.delete(deck.value.id);}
onMounted(async()=>{await initializeTheme();if(props.initialCatalog){catalog.value=props.initialCatalog;catalogItems.value=props.initialCatalog.items;}else await loadCatalog();});
defineExpose({leave,page,deck,rows,sessions});
</script>
<template>
 <div class="unified-shell" :class="{'map-fullscreen':showingMap}">
  <aside v-if="!showingMap" class="unified-sidebar" aria-label="学习导航"><strong>GankSoft</strong><button title="学习总览" aria-label="学习总览" @click="home(folder)"><UiIcon name="summary"/></button><template v-if="deck"><button title="卡片集概览" aria-label="卡片集概览" @click="switchPage('overview')"><UiIcon name="summary"/></button><button title="学习分析" aria-label="学习分析" @click="switchPage('analysis')"><UiIcon name="insights"/></button><button title="所有卡片" aria-label="所有卡片" @click="cards"><UiIcon name="cards"/></button><button title="开始复盘" aria-label="开始复盘" @click="study()"><UiIcon name="schedule"/></button><button title="筛选学习" aria-label="筛选学习" @click="switchPage('planner')"><UiIcon name="search"/></button><button title="复盘调度" aria-label="复盘调度" @click="switchPage('settings')"><UiIcon name="schedule"/></button><button title="卡片回收站" aria-label="卡片回收站" @click="switchPage('recycle')"><UiIcon name="trash"/></button><button title="知识图谱" aria-label="知识图谱" @click="switchPage('knowledge')"><UiIcon name="knowledge"/></button></template><button title="回收站" aria-label="回收站" @click="switchPage('recycle')"><UiIcon name="trash"/></button><button class="system-entry" title="系统设置" aria-label="系统设置" @click="openSystem"><UiIcon name="settings"/></button></aside>
  <div class="unified-main"><header class="unified-topbar"><button v-if="deck" :disabled="busy" @click="home(folder)">‹ 卡片集</button><h1>{{deck?.name??'学习总览'}}</h1><button v-if="page==='system'" @click="returnSystem">返回上一页</button><template v-else-if="showingMap"><button @click="cards">返回所有卡片</button></template><button v-else-if="deck&&page!=='cards'" @click="cards">返回列表</button></header>
   <p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
   <main ref="contentArea" class="unified-content">
    <template v-if="page==='system'"><SystemSettings ref="system" :deck-id="deck?.id" @schedule="switchPage('settings')" @recycle="switchPage('recycle')" @exchange="systemExchange" @restored="reloadAfterRestore"/><Exchange v-if="importing" ref="exchange" importing :parent-id="folder" @close="importing=false" @imported="loadCatalog(folder)"/></template>
    <template v-else-if="page==='home'"><button @click="importing=true">导入卡片内容</button><Exchange v-if="importing" ref="exchange" importing :parent-id="folder" @close="importing=false" @imported="loadCatalog(folder)"/><div class="unified-list-tools"><button title="新建卡片集" aria-label="新建卡片集" @click="catalogEdit={kind:'deck'}"><UiIcon name="add"/>卡片集</button><button title="新建文件夹" aria-label="新建文件夹" @click="catalogEdit={kind:'folder'}"><UiIcon name="add"/>文件夹</button></div><nav aria-label="目录路径"><button @click="loadCatalog(null)">全部卡片集</button><button v-for="b in catalog?.breadcrumbs" :key="b.id" @click="loadCatalog(b.id)">{{b.name}}</button></nav><section class="catalog-grid" aria-label="卡片集目录"><article v-for="item in catalogItems" :key="item.kind+item.id" class="catalog-item" :aria-label="item.name"><button class="catalog-open" @click="item.kind==='folder'?loadCatalog(item.id):openDeck(item)"><UiIcon :name="item.kind==='folder'?'layout':'cards'"/><span>{{item.name}}</span><small v-if="item.kind==='deck'">{{item.cardCount}} 张 · {{item.knowledgeCount}} 个知识点</small></button><button aria-label="管理目录项" :aria-description="item.name" :title="'管理 '+item.name" @click="catalogEdit={kind:item.kind,item}"><UiIcon name="detail"/></button></article><p v-if="!catalogItems.length&&!busy">此目录还没有卡片集。</p></section><button v-if="catalog?.nextCursor" :disabled="busy" @click="loadCatalog(folder,true)">更多卡片集</button></template>
    <template v-else-if="deck&&page==='cards'"><form class="unified-list-tools" @submit.prevent="loadCards()"><input :disabled="busy" v-model="query" aria-label="搜索卡片标题" placeholder="搜索卡片标题"/><select :disabled="busy" v-model="mode" aria-label="卡片模式" @change="loadCards()"><option value="all">全部类型</option><option value="question">单选错题</option><option value="qa">问答记忆</option><option value="direct">直接记忆</option></select><button :disabled="busy">搜索</button><button type="button" @click="restoreDrafts()">恢复草稿</button><details><summary>新建卡片</summary><button v-for="(name,key) in labels" :key="key" type="button" @click="create(key)">{{name}}</button></details></form>
     <nav v-if="drafts.length" aria-label="已保存草稿"><button v-for="d in drafts" :key="d.cardId" @click="viewCard(d.cardId,true)">{{d.title||'未命名草稿'}}</button><button v-if="draftCursor" :disabled="busy" @click="restoreDrafts(true)">更多草稿</button></nav>
     <nav v-if="sessionCursor||sessions.some(s=>!s.completed)" aria-label="恢复复盘页面"><button v-for="s in sessions.filter(s=>!s.completed)" :key="s.sessionId" :title="s.title" @click="resume(s.sessionId)">继续 {{s.title.slice(0,16)}} · {{s.index+1}}/{{s.total}}</button><button v-if="sessionCursor" :disabled="busy" @click="loadSessions(true)">更多复盘页面</button></nav>
     <div v-if="selection.length" class="selection-toolbar" role="toolbar" aria-label="选中卡片操作"><button :disabled="busy" @click="study(selection)">学习选中卡片</button></div><CardBatch ref="batch" :deck-id="deck.id" :cards="selectedRows" @changed="batchSaved" @clear="selection=[]"/>
     <table class="unified-card-list"><thead><tr><th>选择</th><th>卡片</th><th>类型</th><th>排期</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.cardId" :data-card-id="r.cardId"><td><input type="checkbox" :value="r.cardId" v-model="selection" :aria-label="'选择 '+(r.title||'未命名卡片')"/></td><td><button @click="viewCard(r.cardId)">{{r.title||'未命名卡片'}}</button></td><td>{{labels[r.publishedType]}}</td><td>{{r.paused?'已暂停':r.dueAt?new Date(r.dueAt).toLocaleDateString('zh-CN'):'待复盘'}}</td><td><button title="编辑卡片" :aria-label="'编辑 '+r.title" @click="viewCard(r.cardId,true)"><UiIcon name="detail"/></button></td></tr></tbody></table><p v-if="!rows.length&&!busy">没有匹配的卡片，可调整筛选或新建卡片。</p><button v-if="cursor" :disabled="busy" @click="loadCards(true)">更多卡片</button>
    </template>
    <Analytics v-else-if="deck&&(page==='analysis'||page==='overview')" :key="deck.id+page" :deck-id="deck.id" :overview="page==='overview'" @view="(id,eventId)=>viewCard(id,false,eventId)"/>
    <CardRecycle v-else-if="page==='recycle'" ref="recycle" :deck-id="deck?.id" @changed="lastLists.clear();loadCatalog(folder)"/>
    <CardDetail v-else-if="deck&&page==='detail'" ref="detail" :key="cardId" :deck-id="deck.id" :card-id="cardId" :initial-event-id="selectedEvent" @edit="viewCard(cardId,true)" @study="study([cardId])" @schedule="switchPage('card-policy')"/>
    <CardEditor v-else-if="deck&&page==='edit'" :key="cardId" ref="editor" :deck-id="deck.id" :deck-name="deck.name" :card-id="cardId" @published="published"/>
    <template v-else-if="deck&&page==='review'&&review"><nav class="review-tabs" aria-label="复盘页标签"><button v-for="s in sessions" :key="s.sessionId" :title="s.title+' · '+(s.index+1)+'/'+s.total" :aria-current="s.sessionId===activeSession?'page':undefined" @click="resume(s.sessionId)">{{s.title.slice(0,12)}} · {{s.index+1}}/{{s.total}}</button><button v-if="sessionCursor" :disabled="busy" @click="loadSessions(true)">更多复盘页面</button></nav><ReviewForm :key="review.sessionId" ref="reviewForm" :initial="review" :api="unifiedLearning"/></template>
    <StudyPlanner v-else-if="deck&&page==='planner'" :key="deck.id" :deck-id="deck.id" @study="study"/>
    <ScheduleSettings v-else-if="deck&&(page==='settings'||page==='card-policy')" :key="deck.id+page+cardId" ref="settings" :deck-id="deck.id" :card-id="page==='card-policy'?cardId:undefined"/>
    <MindWorkspace v-else-if="deck&&page==='knowledge'" :key="deck.id" ref="map" :unified-deck-id="deck.id" :unified-deck-name="deck.name" expanded @navigate="cards"/>
   </main><CatalogEditor v-if="catalogEdit" ref="catalogEditor" :key="catalogEdit.kind+(catalogEdit.item?.id??'new')" :kind="catalogEdit.kind" :item="catalogEdit.item" :parent-id="catalogEdit.item?.parentId??folder" @saved="catalogSaved" @cancel="catalogEdit=null"/>
  </div>
 </div>
</template>
<style scoped>
.unified-shell{display:grid;grid-template-columns:76px minmax(0,1fr);height:100vh;background:var(--bg,#f5f6f8);color:var(--text,#172033)}.unified-sidebar{display:flex;flex-direction:column;gap:12px;align-items:center;padding:20px 8px;border-right:1px solid var(--line,#ddd)}.unified-sidebar .system-entry{margin-top:auto}.unified-sidebar strong{font-size:12px;margin-bottom:20px}.unified-sidebar button{display:grid;place-items:center;width:42px;height:42px}.unified-main{min-width:0;display:flex;flex-direction:column;overflow:hidden}.unified-topbar{display:flex;align-items:center;gap:16px;padding:12px 24px;border-bottom:1px solid var(--line,#ddd);background:var(--panel,#fff)}.unified-topbar h1{font-size:20px;flex:1;margin:0}.unified-content{flex:1;min-height:0;overflow:auto;padding:24px}.catalog-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:16px;margin-top:24px}.catalog-item{display:grid;grid-template-columns:minmax(0,1fr) 32px;align-items:center;text-align:left;gap:10px;padding:20px;border-radius:12px;background:var(--panel,#fff)}.catalog-open{display:grid;grid-template-columns:24px minmax(0,1fr);gap:10px;align-items:center;text-align:left;border:0;background:transparent;color:inherit;padding:0;min-width:0}.catalog-open span{overflow-wrap:anywhere}.catalog-item small{grid-column:2;color:var(--muted,#64748b)}.unified-list-tools,.selection-toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:18px}.unified-list-tools input{max-width:360px}.unified-card-list{width:100%}.unified-card-list td,.unified-card-list th{padding:14px;text-align:left;border-bottom:1px solid var(--line,#ddd)}.selection-toolbar{padding:12px;background:#eaf2ff;border-radius:10px}.review-tabs{display:flex;gap:8px;overflow:auto}.map-fullscreen{display:block}.map-fullscreen .unified-main{height:100%}.map-fullscreen .unified-content{padding:0}.unified-main>[role=alert],.unified-main>[role=status]{padding:8px 24px;margin:0}button,input,select{font:inherit}button{cursor:pointer}input[type=checkbox]{width:auto}nav button{margin-right:6px}
@media(max-width:760px){.unified-shell{grid-template-columns:58px minmax(0,1fr)}.unified-sidebar{padding:16px 2px}.unified-content{padding:12px}.unified-card-list td,.unified-card-list th{padding:8px}.unified-topbar{padding:10px 12px}.unified-card-list th:nth-child(4),.unified-card-list td:nth-child(4){display:none}}
</style>
